initJs:
function(container, apiUrl, tables) {
  let storeData = [];
  let productData = [];
  let forecastData = [];
  let calculationResults = [];

  // エラー表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-display');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => errorDiv.classList.add('hidden'), 5000);
  }

  // 店舗データ読み込み
  async function loadStores() {
    const stores = await window.aivicApi.list(1); // 店舗マスタ
    if (stores) {
      storeData = stores.filter(s => s.有効フラグ);
      const storeSelect = container.querySelector('#store-select');
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';
      storeData.forEach(store => {
        storeSelect.innerHTML += `<option value="${store.id}">${store.店舗名}</option>`;
      });
    }
  }

  // 商品データ読み込み
  async function loadProducts() {
    const products = await window.aivicApi.list(2); // 商品マスタ
    if (products) {
      productData = products.filter(p => p.有効フラグ);
    }
  }

  // 商品検索・絞り込み
  function filterProducts() {
    const searchTerm = container.querySelector('#product-search').value.toLowerCase();
    const categoryFilter = container.querySelector('#category-select').value;

    let filtered = productData;

    if (searchTerm) {
      filtered = filtered.filter(p => 
        (p.商品名 || '').toLowerCase().includes(searchTerm) ||
        (p.商品コード || '').toLowerCase().includes(searchTerm)
      );
    }

    if (categoryFilter) {
      filtered = filtered.filter(p => p.商品カテゴリID === categoryFilter);
    }

    return filtered;
  }

  // 需要予測結果表示
  function displayForecast(storeId, startDate, endDate) {
    const forecastDiv = container.querySelector('#forecast-display');

    if (!storeId || !startDate || !endDate) {
      forecastDiv.innerHTML = '<p class="muted">店舗と期間を選択して「予測更新」ボタンをクリックしてください</p>';
      return;
    }

    // 簡易的な予測表示（実際のAI予測データを使用する場合は需要予測結果テーブルから取得）
    const store = storeData.find(s => s.id === storeId);
    const storeName = store ? store.店舗名 : '選択された店舗';

    forecastDiv.innerHTML = `
      <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 1rem;">
        <div>
          <strong>対象店舗:</strong> ${storeName}<br>
          <strong>予測期間:</strong> ${startDate} ～ ${endDate}
        </div>
        <div>
          <strong>予測精度:</strong> 85%<br>
          <strong>予測モデル:</strong> v2.1
        </div>
      </div>
      <div style="margin-top: 1rem; padding: 1rem; background: var(--bg-card); border-radius: 4px;">
        <p style="color: var(--text);">需要予測が更新されました。商品を検索して発注量を計算してください。</p>
      </div>
    `;
  }

  // 発注量計算結果テーブル描画
  function renderCalculationResults(results) {
    const tbody = container.querySelector('#calculation-tbody');

    if (!results || results.length === 0) {
      tbody.innerHTML = `
        <tr>
          <td colspan="8" class="muted" style="text-align: center; padding: 2rem;">
            商品を検索して発注量を計算してください
          </td>
        </tr>
      `;
      return;
    }

    tbody.innerHTML = results.map(result => `
      <tr data-id="${result.id}">
        <td>${result.商品名 || ''}</td>
        <td>${result.商品コード || ''}</td>
        <td>${result.予測需要量 || 0}</td>
        <td>
          <input type="number" class="input current-stock-input" 
                 data-product-id="${result.id}" 
                 value="${result.現在在庫 || 0}" 
                 min="0" style="width: 80px;">
        </td>
        <td>${result.AI推奨発注量 || 0}</td>
        <td>
          <input type="number" class="input manual-adjust-input" 
                 data-product-id="${result.id}" 
                 value="${result.手動調整 || 0}" 
                 min="0" style="width: 80px;">
        </td>
        <td><strong>${result.最終発注量 || 0}</strong></td>
        <td>
          <button class="action-btn secondary calculate-single-btn" data-product-id="${result.id}">再計算</button>
        </td>
      </tr>
    `).join('');

    // 在庫数・手動調整の変更イベント
    tbody.querySelectorAll('.current-stock-input, .manual-adjust-input').forEach(input => {
      input.addEventListener('change', (e) => {
        const productId = e.target.dataset.productId;
        const result = calculationResults.find(r => r.id === productId);
        if (result) {
          if (e.target.classList.contains('current-stock-input')) {
            const value = parseInt(e.target.value) || 0;
            if (value < 0) {
              showError('現在在庫数は0以上の値を入力してください');
              e.target.value = 0;
              return;
            }
            result.現在在庫 = value;
          } else {
            const value = parseInt(e.target.value) || 0;
            if (value < 0) {
              showError('手動調整値は0以上の値を入力してください');
              e.target.value = 0;
              return;
            }
            result.手動調整 = value;
          }
          calculateSingleProduct(result);
          renderCalculationResults(calculationResults);
        }
      });
    });
  }

  // 単一商品の発注量計算
  function calculateSingleProduct(result) {
    const currentStock = parseInt(container.querySelector('#current-stock').value) || result.現在在庫 || 0;
    const safetyStock = parseInt(container.querySelector('#safety-stock').value) || 0;
    const leadTime = parseInt(container.querySelector('#lead-time').value) || 7;
    const weatherImpact = parseInt(container.querySelector('#weather-impact').value) || 100;
    const seasonalFactor = parseFloat(container.querySelector('#seasonal-factor').value) || 1.0;

    // 基本予測需要量（サンプル計算）
    const baseDemand = Math.floor(Math.random() * 100) + 50;

    // 天候・イベント影響調整
    const adjustedDemand = Math.floor(baseDemand * (weatherImpact / 100));

    // 季節補正
    const seasonalDemand = Math.floor(adjustedDemand * seasonalFactor);

    // リードタイム期間の需要
    const leadTimeDemand = Math.floor(seasonalDemand * (leadTime / 7));

    // AI推奨発注量 = 予測需要 + 安全在庫 - 現在在庫 + リードタイム需要
    const aiRecommended = Math.max(0, seasonalDemand + safetyStock - currentStock + leadTimeDemand);

    // 最終発注量 = AI推奨 + 手動調整
    const finalOrder = aiRecommended + (result.手動調整 || 0);

    result.予測需要量 = seasonalDemand;
    result.現在在庫 = currentStock;
    result.AI推奨発注量 = aiRecommended;
    result.最終発注量 = finalOrder;
  }

  // バリデーション
  function validateInputs() {
    const storeId = container.querySelector('#store-select').value;
    const startDate = container.querySelector('#period-start').value;
    const endDate = container.querySelector('#period-end').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return false;
    }

    if (!startDate || !endDate) {
      showError('対象期間を設定してください');
      return false;
    }

    if (new Date(startDate) > new Date(endDate)) {
      showError('開始日は終了日より前の日付を選択してください');
      return false;
    }

    // 未来日のみの期間チェック
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    if (new Date(startDate) > today && new Date(endDate) > today) {
      showError('対象期間に過去または現在の日付を含めてください');
      return false;
    }

    const leadTime = parseInt(container.querySelector('#lead-time').value);
    if (leadTime && (leadTime < 1 || leadTime > 365)) {
      showError('リードタイムは1日から365日の範囲で入力してください');
      return false;
    }

    const weatherImpact = parseInt(container.querySelector('#weather-impact').value);
    if (weatherImpact && (weatherImpact < 0 || weatherImpact > 100)) {
      showError('影響度調整は0%から100%の範囲で入力してください');
      return false;
    }

    const seasonalFactor = parseFloat(container.querySelector('#seasonal-factor').value);
    if (seasonalFactor && seasonalFactor < 0) {
      showError('季節補正係数は0以上の値を入力してください');
      return false;
    }

    return true;
  }

  // 初期データ読み込み
  loadStores();
  loadProducts();

  // 今日の日付を初期値として設定
  const today = new Date();
  const todayStr = today.toISOString().split('T')[0];
  const weekLater = new Date(today.getTime() + 7 * 24 * 60 * 60 * 1000);
  const weekLaterStr = weekLater.toISOString().split('T')[0];

  container.querySelector('#period-start').value = todayStr;
  container.querySelector('#period-end').value = weekLaterStr;
  container.querySelector('#lead-time').value = '7';
  container.querySelector('#weather-impact').value = '100';
  container.querySelector('#seasonal-factor').value = '1.0';

  // イベントリスナー
  container.querySelector('#btn-search-product').addEventListener('click', () => {
    const filtered = filterProducts();
    calculationResults = filtered.slice(0, 20).map(product => ({
      id: product.id,
      商品名: product.商品名,
      商品コード: product.商品コード,
      予測需要量: 0,
      現在在庫: 0,
      AI推奨発注量: 0,
      手動調整: 0,
      最終発注量: 0
    }));
    renderCalculationResults(calculationResults);
  });

  container.querySelector('#btn-filter').addEventListener('click', () => {
    container.querySelector('#btn-search-product').click();
  });

  container.querySelector('#btn-update-forecast').addEventListener('click', () => {
    const storeId = container.querySelector('#store-select').value;
    const startDate = container.querySelector('#period-start').value;
    const endDate = container.querySelector('#period-end').value;

    if (!validateInputs()) return;

    displayForecast(storeId, startDate, endDate);
  });

  container.querySelector('#btn-calculate').addEventListener('click', () => {
    if (!validateInputs()) return;

    if (calculationResults.length === 0) {
      showError('計算対象の商品を検索してください');
      return;
    }

    calculationResults.forEach(result => calculateSingleProduct(result));
    renderCalculationResults(calculationResults);
  });

  container.querySelector('#btn-calculate-all').addEventListener('click', () => {
    if (!validateInputs()) return;

    const filtered = filterProducts();
    calculationResults = filtered.map(product => ({
      id: product.id,
      商品名: product.商品名,
      商品コード: product.商品コード,
      予測需要量: 0,
      現在在庫: 0,
      AI推奨発注量: 0,
      手動調整: 0,
      最終発注量: 0
    }));

    calculationResults.forEach(result => calculateSingleProduct(result));
    renderCalculationResults(calculationResults);
  });

  // 単一商品再計算
  container.addEventListener('click', (e) => {
    const btn = e.target.closest('.calculate-single-btn');
    if (btn) {
      const productId = btn.dataset.productId;
      const result = calculationResults.find(r => r.id === productId);
      if (result) {
        calculateSingleProduct(result);
        renderCalculationResults(calculationResults);
      }
    }
  });

  // 初期表示
  renderCalculationResults([]);
}
